-- Add the new hiking, camping and mountaineering trips.
-- Run once in the Supabase SQL editor. Safe to run again: the new trips are
-- written by slug, so a second run just refreshes them.
--
-- What it does, in plain words:
--   1. Hides (unpublishes) every old hiking, camping and mountaineering trip
--      that is not one of the 12 new ones. Nothing is deleted here.
--   2. Adds the 12 new trips, or refreshes them if they are already there.
--      The Kazbek trip keeps its old address (kazbek-summit), so it is updated
--      in place with the new text, price and photos.
--
-- To remove the hidden old trips for good, run DELETE-OLD-OUTDOOR-TRIPS.sql
-- afterwards. Bookings and reviews are not touched either way.
--
-- The new trips are published but not bookable this season: the site shows
-- "Unavailable for now" instead of a booking button. Copy the photos into
-- public/assets/trips/ before the pictures show up.

update public.tours set published = false
  where category in ('hiking', 'camping', 'mountaineering')
    and slug not in ('juta-chaukhi-roshka', 'mestia-ushguli-trek', 'gergeti-trinity-glacier', 'tusheti-omalo-dartlo-diklo', 'abudelauri-lakes-camp', 'black-rock-lake-camp', 'truso-valley-camp', 'koruldi-lakes-camp', 'kazbek-summit', 'tetnuldi-ascent', 'laila-ascent', 'chaukhi-massif-climb');

insert into public.tours (slug, title, subtitle, category, subtype, region, cover_image, gallery, price, distance, duration, difficulty, elevation_gain, stay, languages, capacity, spots_left, badge, season, season_from, season_to, departure_point, departure_time, return_info, transport, group_size, walking_per_day, summary, lat, lng, itinerary, included, excluded, published)
values
  ('juta-chaukhi-roshka', 'Juta to Roshka: Chaukhi Pass & Abudelauri Lakes', 'Chaukhi Pass & Abudelauri lakes', 'hiking', null, 'Mtskheta-Mtianeti', '/assets/trips/juta-chaukhi-roshka-1.webp', array['/assets/trips/juta-chaukhi-roshka-1.webp','/assets/trips/juta-chaukhi-roshka-2.webp','/assets/trips/juta-chaukhi-roshka-3.webp','/assets/trips/juta-chaukhi-roshka-4.webp'], 360, '22 km', '3 days / 2 nights', 'Hard', '1,150 m', 'Guesthouses', 'EN · GE · RU', 10, 10, 'top', 'Mid-July – September', '07-15', '09-30', 'Tbilisi, Liberty Square', '08:00', 'Day 3, ~19:00 Tbilisi', 'Minibus to Juta; our vehicle meets you in Roshka', '4 – 10 people', 'Day 1: 2 hours. Day 2: 8 – 9 hours', 'The best-known crossing in the Greater Caucasus on a short schedule: from the Juta valley under the spires of the Chaukhi massif, over the Chaukhi Pass at about 3,340 m, past the three Abudelauri lakes and down to Roshka in Khevsureti. The pass is the hard part, a long climb with a steep last stretch, and the reward is that you walk out of one valley and into a completely different one in a single day. Snow stays on the saddle until mid-July, so the trip runs only from the second half of July.', 42.5936, 44.7531, '[["Tbilisi → Juta → Tina lake","Drive the Military Road north to Stepantsminda and on up the Juta valley. After lunch, an easy two-hour walk toward Tina lake for the first full view of the Chaukhi massif. Night in a Juta guesthouse."],["Chaukhi Pass → Abudelauri lakes → Roshka","The long day. Early breakfast, then a steady climb to the Chaukhi Pass at about 3,340 m. On the far side the path drops to the Abudelauri lakes (blue, green and white), where we stop for lunch, and continues down the valley to Roshka. Night in a Roshka guesthouse."],["Roshka → Tbilisi","A slow morning, then the drive back to Tbilisi by way of the Pshavi and Aragvi valleys."]]'::jsonb, '[["Mountain guides","Two certified guides on the pass day, first-aid trained"],["2 nights in guesthouses","One in Juta, one in Roshka, shared rooms"],["Meals","Breakfast and dinner on both nights, picnic lunch on the pass day"],["Transport","Minibus Tbilisi – Juta, and a vehicle waiting in Roshka for the return"],["First aid kit","Carried by the guides"]]'::jsonb, '[["Personal gear","Walking boots, rain shell, warm layer, poles if you use them"],["Travel insurance","Required, and it must cover walking above 3,000 m"],["Day-one lunch","Bought on the way, roughly 20 – 30 ₾"],["Horse for luggage","Possible on request, charged separately"]]'::jsonb, true),
  ('mestia-ushguli-trek', 'Mestia – Ushguli Trek', 'Mestia → Ushguli trek', 'hiking', null, 'Svaneti', '/assets/trips/mestia-ushguli-trek-1.webp', array['/assets/trips/mestia-ushguli-trek-1.webp','/assets/trips/mestia-ushguli-trek-2.webp','/assets/trips/mestia-ushguli-trek-3.webp','/assets/trips/mestia-ushguli-trek-4.webp'], 890, '55 km', '4 days / 3 nights', 'Medium', '2,400 m', 'Guesthouses', 'EN · GE · RU', 12, 12, 'top', 'Late June – September', '06-20', '09-30', 'Mestia, town centre', '08:00', 'Day 4, ~16:00 Ushguli, then shared transfer to Mestia', 'Walking; 4x4 from Ushguli back to Mestia', '4 – 12 people', '5 – 8 hours', 'Four walking days through Upper Svaneti, from Mestia to Ushguli, one of the highest permanently inhabited villages in Europe. You cross the Chkhunderi Pass at about 2,700 m, pass the Adishi glacier valley and sleep in family guesthouses in Zhabeshi, Adishi and Iprali, with Svan stone towers in every village and Shkhara standing over the last day. The trail is not steep for long, but the days are long. We start in Mestia; a Tbilisi or Kutaisi transfer can be added.', 43.0456, 42.7297, '[["Mestia → Zhabeshi","Out of Mestia along the Mulkhura valley, about 16 km with some 770 m of climbing. Svan towers in the villages, and the first good views of Tetnuldi. Night in Zhabeshi."],["Zhabeshi → Chkhunderi Pass → Adishi","A steep first hour through rhododendron forest, then open slopes up to the Chkhunderi Pass at about 2,700 m. The path drops into Adishi, a village of towers at 2,050 m, with the Adishi glacier valley behind it."],["Adishi → Iprali","The longest day by distance. A last look at the glacier, a steep descent, then mostly flat walking beside the Adishi river with a couple of crossings. Night in Iprali."],["Iprali → Ushguli","An undulating trail through Davberi to Ushguli and its four villages under Shkhara. Time at the Lamaria church, lunch, and a shared 4x4 transfer back to Mestia."]]'::jsonb, '[["Mountain guide","Certified, first-aid trained; two guides for groups over 8"],["3 nights in guesthouses","Zhabeshi, Adishi and Iprali, shared rooms"],["Meals","Breakfast and dinner every day, picnic lunches on the trail"],["Luggage transport","Large bags are moved by road between villages when the road allows it"],["Transfer Ushguli → Mestia","Shared 4x4 on day 4"],["First aid kit","Carried by the guide"]]'::jsonb, '[["Getting to Mestia","Tbilisi or Kutaisi transfers, flights and marshrutkas are not included; we can arrange a private transfer"],["Personal gear","Boots, rain shell, warm layer, sleeping liner"],["Travel insurance","Required, arrange before arrival"],["Extra snacks and drinks","Bought in the villages"]]'::jsonb, true),
  ('gergeti-trinity-glacier', 'Kazbegi – Gergeti Trinity & Glacier', 'Gergeti Trinity & glacier', 'hiking', null, 'Mtskheta-Mtianeti', '/assets/trips/gergeti-trinity-glacier-1.webp', array['/assets/trips/gergeti-trinity-glacier-1.webp','/assets/trips/gergeti-trinity-glacier-2.webp','/assets/trips/gergeti-trinity-glacier-3.webp','/assets/trips/gergeti-trinity-glacier-4.webp'], 340, '16 km', '2 days / 1 night', 'Medium', '1,300 m', 'Guesthouse', 'EN · GE · RU', 12, 12, null, 'Mid-June – mid-October', '06-15', '10-15', 'Tbilisi, Liberty Square', '08:00', 'Day 2, ~21:00 Tbilisi', 'Minibus both ways', '4 – 12 people', 'Day 1: 2 hours. Day 2: 6 – 7 hours', 'The classic Georgian view, walked rather than photographed from a car. On the first afternoon you climb from Stepantsminda to Gergeti Trinity church at 2,170 m with Mount Kazbek behind it. On the second day you keep going up the Chkheri valley toward the moraine below the Gergeti glacier, an unmarked path on loose ground with one of the closest views of Kazbek you can get without crampons.', 42.6575, 44.6453, '[["Tbilisi → Stepantsminda → Gergeti Trinity","Drive the Georgian Military Road with stops at Ananuri fortress and the Friendship monument viewpoint at the Jvari pass. After checking in, walk up to Gergeti Trinity church for the evening light on Kazbek. Night in a Stepantsminda guesthouse."],["Gergeti glacier moraine → Tbilisi","Early start past the church and on up toward the moraine below the Gergeti glacier, about 6 to 7 hours there and back. A late lunch in Stepantsminda, then the drive to Tbilisi."]]'::jsonb, '[["Mountain guide","Certified, first-aid trained, English-speaking"],["1 night in a guesthouse","Stepantsminda, shared room, breakfast included"],["Dinner on day 1","At the guesthouse"],["Transport","Minibus Tbilisi – Stepantsminda – Tbilisi"],["First aid kit","Carried by the guide"]]'::jsonb, '[["Lunches","Picnic or café lunch on both days, roughly 20 – 30 ₾ a day"],["Personal gear","Boots, rain shell, warm layer, sun protection"],["Travel insurance","Required, arrange before arrival"],["Car up to the church","Taxis run to the church; we walk, and a lift is paid locally"]]'::jsonb, true),
  ('tusheti-omalo-dartlo-diklo', 'Tusheti Trek: Omalo, Diklo & Dartlo', 'Omalo, Diklo & Dartlo', 'hiking', null, 'Tusheti', '/assets/trips/tusheti-omalo-dartlo-diklo-1.webp', array['/assets/trips/tusheti-omalo-dartlo-diklo-1.webp','/assets/trips/tusheti-omalo-dartlo-diklo-2.webp','/assets/trips/tusheti-omalo-dartlo-diklo-3.webp','/assets/trips/tusheti-omalo-dartlo-diklo-4.webp'], 780, '20 km', '4 days / 3 nights', 'Medium', '1,350 m', 'Guesthouses', 'EN · GE · RU', 10, 10, 'new', 'Late June – September', '06-25', '09-25', 'Tbilisi, Liberty Square', '07:00', 'Day 4, ~22:00 Tbilisi', '4x4 over the Abano Pass', '4 – 10 people', '4 – 5 hours on days 2 and 3', 'Tusheti is reached over the Abano Pass, one of the highest drivable roads in Georgia, and is cut off from the rest of the country for much of the year. This trip spends two days on the road and two on foot: Omalo and its Keshelo fortress, the walk through Shenako to Diklo near the Russian border, then over the Tutareki Pass at 1,911 m to Dartlo, a village of stone towers and slate roofs. Sleeping is in family guesthouses, and the walking days are four to five hours each.', 42.3789, 45.63, '[["Tbilisi → Abano Pass → Omalo","A full day on the road: through Kakheti and Pshaveli, then the unpaved Abano Pass road in 4x4s, arriving in Omalo in the late afternoon. A short walk up to Keshelo fortress, dinner and night in a guesthouse."],["Omalo → Shenako → Diklo","About 11 km and 5 hours with roughly 650 m of climbing, through Shenako to Diklo, a village close to the Russian border with its own fortress. Night in a Diklo guesthouse."],["Diklo → Tutareki Pass → Dartlo","The Tutareki Pass at 1,911 m, then down to Dartlo, about 8.6 km and 4 hours. Short, but with climbing on both sides. Time in the village before dinner."],["Dartlo → Omalo → Tbilisi","A morning in Dartlo, the 4x4 back to Omalo and over the Abano Pass, and the long drive to Tbilisi."]]'::jsonb, '[["Mountain guide","Certified, first-aid trained, English-speaking"],["3 nights in guesthouses","Omalo, Diklo and Dartlo, shared rooms"],["Meals","Breakfast and dinner every day, picnic lunches on the walking days"],["4x4 transport","Tbilisi – Omalo – Tbilisi, including the Abano Pass"],["Park fees","Tusheti National Park entry"]]'::jsonb, '[["Lunch on the driving days","Roadside stops, roughly 20 – 30 ₾ each"],["Personal gear","Boots, rain shell, warm layer, sleeping liner"],["Travel insurance","Required, arrange before arrival"],["Horses","Available in Omalo for luggage, charged locally"]]'::jsonb, true),
  ('abudelauri-lakes-camp', 'Abudelauri Lakes Camp', 'Three lakes under Chaukhi', 'camping', null, 'Mtskheta-Mtianeti', '/assets/trips/abudelauri-lakes-camp-1.webp', array['/assets/trips/abudelauri-lakes-camp-1.webp','/assets/trips/abudelauri-lakes-camp-2.webp','/assets/trips/abudelauri-lakes-camp-3.webp','/assets/trips/abudelauri-lakes-camp-4.webp'], 480, '20 km', '3 days / 2 nights', 'Medium', '1,100 m', 'Tents', 'EN · GE · RU', 10, 10, 'top', 'July – September', '07-01', '09-30', 'Tbilisi, Liberty Square', '08:00', 'Day 3, ~19:00 Tbilisi', 'Minibus to Roshka', '4 – 10 people', '3 – 6 hours', 'Two nights in tents beside the Abudelauri lakes in Khevsureti, three alpine lakes (blue, green and white) at the foot of the Chaukhi massif. You walk up from the village of Roshka on the first afternoon, spend the middle day around the lakes with time to go as far as the foot of the Chaukhi Pass, and come down on the third morning. Shorter days than the Juta crossing, with the same scenery.', 42.5575, 44.8444, '[["Tbilisi → Roshka → lower lakes","Drive through the Pshavi and Aragvi valleys to Roshka (about 4 hours). After lunch, a steady walk of roughly 5 km up the valley to the lower lakes. We pitch camp and cook dinner."],["Lakes and Chaukhi Pass viewpoint","A day at altitude with a light pack: the blue, green and white lakes, and a climb toward the foot of the Chaukhi Pass for the view of the massif. Back to camp for dinner."],["Camp → Roshka → Tbilisi","Breakfast, break camp, walk down to Roshka and drive back to Tbilisi."]]'::jsonb, '[["Mountain guide","Certified, first-aid trained"],["Tents and mats","Two-person tents and sleeping mats, pitched at camp"],["Camp meals","Dinner on days 1 and 2, breakfast on days 2 and 3, picnic lunches"],["Transport","Minibus Tbilisi – Roshka – Tbilisi"],["Gear carriage","Tents and food are carried by horse to the lower lakes"],["First aid kit","Carried by the guide"]]'::jsonb, '[["Sleeping bag","Bring one rated to 0 °C, or hire from us"],["Personal gear","Boots, rain shell, warm layers, headlamp"],["Travel insurance","Required, arrange before arrival"],["Day-one lunch","Bought on the way, roughly 20 – 30 ₾"]]'::jsonb, true),
  ('black-rock-lake-camp', 'Lagodekhi: Black Rock Lake Camp', 'Black Rock Lake trek', 'camping', null, 'Kakheti', '/assets/trips/black-rock-lake-camp-1.webp', array['/assets/trips/black-rock-lake-camp-1.webp','/assets/trips/black-rock-lake-camp-2.webp','/assets/trips/black-rock-lake-camp-3.webp','/assets/trips/black-rock-lake-camp-4.webp'], 640, '38 km', '4 days / 3 nights', 'Hard', '2,250 m', 'Tents', 'EN · GE · RU', 8, 8, 'new', 'Late June – September', '06-25', '09-20', 'Tbilisi, Liberty Square', '07:30', 'Day 4, ~20:00 Tbilisi', 'Minibus Tbilisi – Lagodekhi', '4 – 8 people', '5 – 8 hours', 'A four-day return walk from the Lagodekhi Protected Areas, on Georgia''s eastern edge, up through forest and then open alpine ground to Black Rock Lake at roughly 2,800 m, close to the Dagestan border ridge. It is a long, steep climb, with a night out in tents on the way up and another near the lake. The park requires registration in advance, and we do that for you.', 41.8222, 46.275, '[["Tbilisi → Lagodekhi → first camp","Drive east to Lagodekhi, register at the park visitor centre, and walk into the forest to the first camp, with a stop at the Ninoskhevi waterfall if time allows."],["Forest camp → high camp","The steep day: out of the trees and up onto the open slopes toward the lake basin. Camp below the lake."],["Black Rock Lake → back down","A short climb to Black Rock Lake with a long stop on the shore, then down to the lower camp for the night."],["Lower camp → Tbilisi","Walk out to the park entrance after breakfast and drive back to Tbilisi."]]'::jsonb, '[["Mountain guide","Certified, first-aid trained"],["Park registration","Lagodekhi Protected Areas permit arranged for you"],["Tents and mats","Two-person tents and sleeping mats"],["Camp meals","Dinner and breakfast at camp, picnic lunches on the trail"],["Transport","Minibus Tbilisi – Lagodekhi – Tbilisi"],["First aid kit","Carried by the guide"]]'::jsonb, '[["Sleeping bag","Bring one rated to 0 °C, or hire from us"],["Personal gear","Boots, rain shell, warm layers, headlamp, poles"],["Travel insurance","Required, arrange before arrival"],["Day-one lunch","Bought on the way, roughly 20 – 30 ₾"]]'::jsonb, true),
  ('truso-valley-camp', 'Truso Valley Camp', 'Valley camp near Kazbegi', 'camping', null, 'Mtskheta-Mtianeti', '/assets/trips/truso-valley-camp-1.webp', array['/assets/trips/truso-valley-camp-1.webp','/assets/trips/truso-valley-camp-2.webp','/assets/trips/truso-valley-camp-3.webp','/assets/trips/truso-valley-camp-4.webp'], 420, '22 km', '3 days / 2 nights', 'Easy', '500 m', 'Tents', 'EN · GE · RU', 12, 12, null, 'June – September', '06-01', '09-30', 'Tbilisi, Liberty Square', '09:00', 'Day 3, ~20:00 Tbilisi', 'Minibus + 4x4 into the valley', '4 – 12 people', '2 – 6 hours', 'A relaxed two nights in the Truso valley west of Kazbegi, a wide river valley with mineral springs, orange travertine terraces, old stone villages and the ruined Zakagori fortress at its end. The walking is mostly flat, around 22 km over the middle day, and fits first-time campers and families with older children. The valley is a border-zone area, so we handle the paperwork.', 42.6, 44.48, '[["Tbilisi → Truso valley → camp","Drive the Military Road to Kvemo Okrokana and take the 4x4 track into the valley. Short walk to the camp site near Ketrisi, tents up before dinner."],["Mineral springs → Zakagori fortress","Walk up the valley past the Abano mineral lake and the travertine terraces to the ruined Zakagori fortress. Lunch by the river, then a flat return to camp."],["Camp → Stepantsminda → Tbilisi","Pack up, 4x4 out of the valley, lunch in Stepantsminda and the drive back."]]'::jsonb, '[["Mountain guide","Certified, first-aid trained"],["Tents and mats","Two-person tents and sleeping mats, pitched at camp"],["Camp meals","Dinner and breakfast at camp, picnic lunches"],["Transport","Minibus Tbilisi – Kazbegi and 4x4 into the valley"],["Border-zone paperwork","Arranged for the group"],["First aid kit","Carried by the guide"]]'::jsonb, '[["Sleeping bag","Bring one rated to 5 °C, or hire from us"],["Personal gear","Boots, rain shell, warm layer, sun protection"],["Travel insurance","Required, arrange before arrival"],["Day-three lunch","In Stepantsminda, roughly 20 – 30 ₾"]]'::jsonb, true),
  ('koruldi-lakes-camp', 'Koruldi Lakes Camp', 'Koruldi lakes camp', 'camping', null, 'Svaneti', '/assets/trips/koruldi-lakes-camp-1.webp', array['/assets/trips/koruldi-lakes-camp-1.webp','/assets/trips/koruldi-lakes-camp-2.webp','/assets/trips/koruldi-lakes-camp-3.webp','/assets/trips/koruldi-lakes-camp-4.webp'], 420, '20 km', '3 days / 2 nights', 'Medium', '1,200 m', 'Tents', 'EN · GE · RU', 10, 10, null, 'Late June – September', '06-25', '09-25', 'Mestia, town centre', '09:00', 'Day 3, ~16:00 Mestia', 'Walking from Mestia; optional 4x4 to the viewpoint', '4 – 10 people', '4 – 6 hours', 'The Koruldi lakes sit about 1,200 m above Mestia, at roughly 2,750 m, with the Ushba and Tetnuldi ranges in front of them. Most visitors do the climb as a day trip and leave by early afternoon. This trip stays two nights in tents by the lakes, so you have the evening and the sunrise to yourselves, and a free middle day for the Koruldi ridge cross at about 3,330 m. We meet in Mestia; Tbilisi transfers can be added.', 43.0456, 42.7297, '[["Mestia → Koruldi lakes","Leave Mestia and climb through the forest to the lakes, about 1,200 m of ascent. Camp is pitched near the shore, with dinner as the light goes."],["Koruldi ridge cross","A full day with a light pack: up to the Koruldi ridge at about 3,330 m for the view of the central Caucasus and back. Anyone who prefers a rest day can stay by the lakes."],["Lakes → Mestia","Break camp after breakfast and walk down to Mestia, with lunch in town."]]'::jsonb, '[["Mountain guide","Certified, first-aid trained"],["Tents and mats","Two-person tents and sleeping mats"],["Camp meals","Dinner on days 1 and 2, breakfast on days 2 and 3, picnic lunches"],["Gear carriage","Tents and food go up by 4x4 and horse where the track allows"],["First aid kit","Carried by the guide"]]'::jsonb, '[["Getting to Mestia","Tbilisi and Kutaisi transfers are not included; we can arrange a private transfer"],["Sleeping bag","Bring one rated to 0 °C, or hire from us"],["Personal gear","Boots, rain shell, warm layers, headlamp"],["Travel insurance","Required, arrange before arrival"]]'::jsonb, true),
  ('kazbek-summit', 'Mount Kazbek Summit Climb', '5,054 m summit climb', 'mountaineering', null, 'Kazbegi', '/assets/trips/kazbek-summit-1.webp', array['/assets/trips/kazbek-summit-1.webp','/assets/trips/kazbek-summit-2.webp','/assets/trips/kazbek-summit-3.webp','/assets/trips/kazbek-summit-4.webp'], 1450, '36 km', '7 days / 6 nights', 'Hard', '3,300 m', 'Guesthouse, meteo station & tents', 'EN · GE · RU', 8, 8, 'top', 'Late June – early September', '06-25', '09-10', 'Tbilisi, Liberty Square', '08:00', 'Day 7, ~20:00 Tbilisi', 'Minibus Tbilisi – Stepantsminda; 4x4 to Gergeti', '2 – 8 people, one guide per two climbers on summit day', '5 – 12 hours', 'A guided ascent of Kazbek (Mkinvartsveri), the classic Georgian glacier peak at 5,054 m. Two nights in Stepantsminda to get used to the height, an acclimatisation climb past Gergeti Trinity, a night at the meteo station at about 3,650 m, glacier and crampon training, then a summit push in the dark. A reserve day is built in for weather. For fit hikers ready for their first big mountain; no previous crampon experience is needed, but you will learn it here.', 42.6997, 44.5186, '[["Tbilisi → Stepantsminda","Drive the Military Road north, gear check and an evening briefing with the guide."],["Gergeti → Sabertse Pass","First climb past the Trinity church to around 3,000 m for acclimatisation, back down to sleep in town."],["Up to the meteo station","Cross the Gergeti glacier moraine to the station at about 3,650 m. Night in the station or in tents."],["Acclimatisation & glacier school","A climb to around 4,200 m, rope work, crampons and ice-axe arrest on the glacier."],["Summit day","Start around 01:00, summit at sunrise at 5,054 m, back to the station by afternoon."],["Reserve day","Kept free in case the weather closes the summit window; if the summit is done, a rest day and an easy walk down."],["Down → Tbilisi","Walk out to Gergeti and drive back to the city."]]'::jsonb, '[["Mountain guides","IFMGA-qualified lead guide, one guide to every two climbers on summit day"],["Group gear","Ropes, tents, stoves and fuel"],["Accommodation","Guesthouse in Stepantsminda, meteo station bunks and tents on the mountain"],["Meals","Breakfast, lunch and dinner for all seven days"],["Transport","Minibus Tbilisi – Stepantsminda – Tbilisi and 4x4 to the trailhead"],["Permits","Kazbegi National Park and border-zone paperwork"],["First aid and radio","Medical kit and a satellite or radio link carried by the lead guide"]]'::jsonb, '[["Personal technical gear","Boots, crampons, harness, ice axe, helmet; hire available"],["Sleeping bag","Rated to -15 °C or lower, or hire from us"],["Travel insurance","Must cover climbing to 5,000 m, including rescue"],["Porters and horses","To the meteo station on request, charged separately"]]'::jsonb, true),
  ('tetnuldi-ascent', 'Mount Tetnuldi Ascent', '4,858 m via the south-west ridge', 'mountaineering', null, 'Svaneti', '/assets/trips/tetnuldi-ascent-1.webp', array['/assets/trips/tetnuldi-ascent-1.webp','/assets/trips/tetnuldi-ascent-2.webp','/assets/trips/tetnuldi-ascent-3.webp','/assets/trips/tetnuldi-ascent-4.webp'], 1250, null, '5 days / 4 nights', 'Hard', '2,150 m', 'Tents on the glacier', 'EN · GE · RU', 6, 6, 'new', 'Mid-July – early September', '07-10', '09-05', 'Mestia, town centre', '08:00', 'Day 5, ~17:00 Mestia', '4x4 from Mestia to the start of the route', '2 – 6 people, one guide per two climbers', '4 – 10 hours', 'Tetnuldi, at about 4,858 m, is the most accessible high peak in Svaneti and a good second step after Kazbek. The normal route follows the south-west ridge from the Adishi valley: a grassy first camp, a second camp on the lower glacier and a third camp on the ridge about 500 m below the summit, with a graded PD+ ridge to the top. Summit day is about eight hours up and four to five down. Good fitness and basic crampon skills help; we revise them on the way.', 43.0311, 42.9932, '[["Mestia → camp 1","Gear check in Mestia, 4x4 toward the start of the route, and a walk of a few hours to the first camp on the grassy slopes below the moraine, around 2,900 m."],["Camp 1 → camp 2 on the glacier","Up the moraine and onto the lower glacier. Rope and crampon revision, then camp on the ice-free edge."],["Camp 2 → camp 3 on the ridge","Steeper ground up to the south-west ridge, where the route joins it. Camp about 500 m below the summit. Early dinner and bed."],["Summit day","Start in the dark, about eight hours to the summit by the PD+ ridge, and four to five hours back down to the camp or lower."],["Descent → Mestia","Back down to the 4x4 and the drive to Mestia. A reserve day is not built in, so a weather delay is taken from this day."]]'::jsonb, '[["Mountain guides","Certified guide, one to every two climbers"],["Group gear","Ropes, tents, stoves and fuel"],["Meals","All meals on the mountain, from lunch on day 1 to lunch on day 5"],["Transport","4x4 from Mestia to the start and back"],["Permits","Border-zone and park paperwork where it applies"],["First aid kit","Carried by the guide"]]'::jsonb, '[["Personal technical gear","Boots, crampons, harness, ice axe, helmet; hire available"],["Sleeping bag","Rated to -10 °C or lower, or hire from us"],["Travel insurance","Must cover climbing to 5,000 m, including rescue"],["Getting to Mestia","Tbilisi or Kutaisi transfers; we can arrange them"]]'::jsonb, true),
  ('laila-ascent', 'Mount Laila Ascent', '4,008 m via Tskhumari', 'mountaineering', null, 'Svaneti', '/assets/trips/laila-ascent-1.webp', array['/assets/trips/laila-ascent-1.webp','/assets/trips/laila-ascent-2.webp','/assets/trips/laila-ascent-3.webp','/assets/trips/laila-ascent-4.webp'], 780, null, '4 days / 3 nights', 'Hard', '1,500 m to camp, 1,200 m to the summit', 'Tents', 'EN · GE · RU', 6, 6, 'new', 'Mid-July – September', '07-15', '09-30', 'Mestia, town centre', '07:00', 'Day 4, ~16:00 Mestia', '4x4 Mestia – Tskhumari – Mestia', '2 – 6 people, one guide per two climbers', 'Day 1: 5 – 6 hours. Day 2: 6 – 7 hours up and back from camp', 'Laila (Lahili) is a 4,008 m peak in the Svaneti range, south of Mestia, and one of the more approachable 4,000 m summits in Georgia. The route starts in the village of Tskhumari at about 1,300 m, climbs through forest and along a ridge to a camp at about 2,800 m, and finishes on a glacier summit day where everyone is roped up in teams. A reserve day is built in for weather or slow acclimatisation. Good fitness and a head for height matter more than technical skill.', 42.9202, 42.557, '[["Mestia → Tskhumari → camp","Gear check in Mestia, then a 4x4 to Tskhumari at about 1,300 m. A steady climb through forest and along the ridge, around 1,500 m of ascent in five to six hours, to the camp at about 2,800 m. Tents up and an early dinner."],["Summit day","Start at dawn, roped up in teams across the glacier, about 1,200 m to the 4,008 m summit. Allow six to seven hours for the round trip back to camp."],["Reserve day","Kept for bad weather or a slow acclimatisation. If the summit is done, a rest day at camp or an early start down."],["Camp → Tskhumari → Mestia","Break camp, walk down to Tskhumari and take the 4x4 back to Mestia in the afternoon."]]'::jsonb, '[["Mountain guides","Certified guide, one to every two climbers on summit day"],["Group gear","Ropes, tents, stoves and fuel"],["Camp meals","All meals from lunch on day 1 to lunch on day 4"],["Transport","4x4 Mestia – Tskhumari – Mestia"],["First aid kit","Carried by the guide"]]'::jsonb, '[["Personal technical gear","Boots, crampons, harness, ice axe, helmet; hire available"],["Sleeping bag","Rated to -5 °C or lower, or hire from us"],["Travel insurance","Must cover climbing to 4,000 m, including rescue"],["Getting to Mestia","Tbilisi or Kutaisi transfers; we can arrange them"]]'::jsonb, true),
  ('chaukhi-massif-climb', 'Chaukhi Massif: Guided Scramble', 'Scrambling on the massif', 'mountaineering', null, 'Mtskheta-Mtianeti', '/assets/trips/chaukhi-massif-climb-1.webp', array['/assets/trips/chaukhi-massif-climb-1.webp','/assets/trips/chaukhi-massif-climb-2.webp','/assets/trips/chaukhi-massif-climb-3.webp','/assets/trips/chaukhi-massif-climb-4.webp'], 520, '16 km', '3 days / 2 nights', 'Hard', '1,500 m', 'Guesthouse & tents', 'EN · GE · RU', 6, 6, 'new', 'Mid-July – September', '07-15', '09-20', 'Tbilisi, Liberty Square', '08:00', 'Day 3, ~20:00 Tbilisi', 'Minibus to Juta', '2 – 6 people, one guide per two climbers', '3 – 8 hours', 'The Chaukhi massif is the jagged rock wall above the Juta valley, with summits around 3,800 m and the pass at about 3,340 m. This is a short trip for hikers who want to try real rock: a night in Juta, a night in tents near the pass, and a day of guided scrambling and easy roped sections on the pass ridge. The guide chooses the line on the day according to the group, the weather and the rock. No technical grade is promised.', 42.5936, 44.7531, '[["Tbilisi → Juta → Tina lake","Drive to Juta and walk up to the Tina lake area for the first look at the massif. Gear check and a short briefing on moving on rock. Night in a Juta guesthouse."],["Up to the pass ridge","Climb toward the Chaukhi Pass and camp near its foot. In the afternoon, a first guided scramble with ropes where the guide decides they are needed. Night in tents."],["Ridge day → Juta → Tbilisi","An early start for the ridge, back to camp for a late breakfast, then down to Juta and the drive to Tbilisi."]]'::jsonb, '[["Mountain guides","Certified guide, one to every two climbers on the ridge"],["Climbing gear","Ropes, helmets and harnesses for the group"],["Accommodation","One night in a Juta guesthouse and one in tents near the pass"],["Meals","Breakfast and dinner on both nights, picnic lunches"],["Transport","Minibus Tbilisi – Juta – Tbilisi"],["First aid kit","Carried by the guide"]]'::jsonb, '[["Personal gear","Boots with a stiff sole, rain shell, warm layers, gloves"],["Sleeping bag","Rated to -5 °C or lower, or hire from us"],["Travel insurance","Must cover climbing, including rescue"],["Day-one lunch","Bought on the way, roughly 20 – 30 ₾"]]'::jsonb, true)
